class Solution {
  public int minCost(int[][] grid, int k) {
    int m = grid.length, n = grid[0].length, INF = Integer.MAX_VALUE / 2;
    int maxV = 0;
    for (int[] row : grid) for (int v : row) maxV = Math.max(maxV, v);
    int[][] prev = null, cur = new int[m][n];
    for (int t = 0; t <= k; t++) {
      int[] suffix = new int[maxV + 2];
      java.util.Arrays.fill(suffix, INF);
      if (prev != null) {
        for (int i = 0; i < m; i++)
          for (int j = 0; j < n; j++) suffix[grid[i][j]] = Math.min(suffix[grid[i][j]], prev[i][j]);
        for (int v = maxV - 1; v >= 0; v--) suffix[v] = Math.min(suffix[v], suffix[v + 1]);
      }
      for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
          int best = prev != null ? suffix[grid[i][j]] : INF;
          if (i == 0 && j == 0) best = 0;
          else {
            if (i > 0) best = Math.min(best, cur[i - 1][j] + grid[i][j]);
            if (j > 0) best = Math.min(best, cur[i][j - 1] + grid[i][j]);
          }
          cur[i][j] = best;
        }
      }
      int[][] tmp = prev == null ? new int[m][n] : prev;
      prev = cur;
      cur = tmp;
    }
    return prev[m - 1][n - 1];
  }
}
